export const WORDS: Word[] = [
  ...A1_WORDS, ...A2_WORDS, ...B1_WORDS, ...B2_WORDS, ...C1_WORDS, ...C2_WORDS,
];

export const getWordsByLevel = (level: Level): Word[] =>
  WORDS.filter(w => w.level === level).sort((a, b) => a.english.localeCompare(b.english));

export const getWordCountByLevel = (level: Level): number =>
  WORDS.filter(w => w.level === level).length;
